CREATE TABLE `scalar_compact` (
  `id` int(11) NOT NULL,
  `ti` tinyint(4) DEFAULT NULL,
  `tu` tinyint(3) unsigned DEFAULT NULL,
  `sm` smallint(6) DEFAULT NULL,
  `su` smallint(5) unsigned DEFAULT NULL,
  `med` mediumint(9) DEFAULT NULL,
  `mu` mediumint(8) unsigned DEFAULT NULL,
  `si` int(11) DEFAULT NULL,
  `iu` int(10) unsigned DEFAULT NULL,
  `bi` bigint(20) DEFAULT NULL,
  `bu` bigint(20) unsigned DEFAULT NULL,
  `decv` decimal(65,30) DEFAULT NULL,
  `fv` float DEFAULT NULL,
  `dv` double DEFAULT NULL,
  `bv` bit(64) DEFAULT NULL,
  `y` year(4) DEFAULT NULL,
  `d` date DEFAULT NULL,
  `dt` datetime(6) DEFAULT NULL,
  `tm` time(6) DEFAULT NULL,
  `ts` timestamp(6) NULL DEFAULT NULL,
  `ch` char(8) COLLATE utf8mb4_bin DEFAULT NULL,
  `v` varchar(300) COLLATE utf8mb4_bin DEFAULT NULL,
  `b` binary(5) DEFAULT NULL,
  `vb` varbinary(300) DEFAULT NULL,
  `e` enum('','界','O''Brien','a,b','back\\slash') COLLATE utf8mb4_bin DEFAULT NULL,
  `s` set('界','O''Brien','back\\slash') COLLATE utf8mb4_bin DEFAULT NULL,
  `j` json DEFAULT NULL,
  `g` geometry DEFAULT NULL,
  `p` point DEFAULT NULL,
  `line` linestring DEFAULT NULL,
  `poly` polygon DEFAULT NULL,
  `mp` multipoint DEFAULT NULL,
  `ml` multilinestring DEFAULT NULL,
  `mpoly` multipolygon DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=COMPACT;
